"}, {"path": "css/styles.css", "content": "/* IKEA BESTÅ demo – styles */
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{font-family:Arial,Helvetica,sans-serif;color:#111;font-size:14px;line-height:1.45;background:#fff;-webkit-font-smoothing:antialiased}
img{display:block;max-width:100%}
button{font-family:inherit;cursor:pointer;background:none;border:none;color:inherit;font-size:inherit}
a{color:inherit;text-decoration:none;cursor:pointer}
.wrap{max-width:1440px;margin:0 auto;padding:0 48px}
.hidden{display:none!important}
.muted{color:#6f6f6f}

/* ---------- top bar ---------- */
.topbar{background:#111;color:#fff;height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 48px;font-size:13px;position:relative;z-index:120}
.topbar svg{width:18px;height:18px;stroke:#fff;fill:none;stroke-width:1.6;vertical-align:-4px}
.tb-left{display:flex;align-items:center;gap:8px}
.tb-center{font-weight:700;display:flex;gap:8px;align-items:center;position:absolute;left:50%;transform:translateX(-50%)}
.tb-right{display:flex;align-items:center;gap:28px}
.tb-item{display:flex;align-items:center;gap:8px;font-weight:700;cursor:pointer;white-space:nowrap}
.tb-item:hover{text-decoration:underline}

/* ---------- main header ---------- */
.mainhead{display:flex;align-items:center;gap:36px;padding:14px 48px;background:#fff;position:relative;z-index:110}
.logo{display:block;flex:0 0 auto}
.mainnav{display:flex;gap:28px;flex:0 0 auto}
.navlink{font-size:14px;color:#111;padding:6px 0;background:none;border:none;cursor:pointer;white-space:nowrap}
.navlink:hover{text-decoration:underline}
.navlink.active{font-weight:700;text-decoration:underline;text-underline-offset:4px}
.searchbox{position:relative;flex:0 1 340px;min-width:220px}
.searchbox input{width:100%;height:48px;border:none;background:#f5f5f5;border-radius:999px;padding:0 84px 0 44px;font-size:15px;outline:none}
.searchbox input:focus{background:#fff;box-shadow:inset 0 0 0 2px #0058a3}
.searchbox .s-icon{position:absolute;left:16px;top:50%;transform:translateY(-50%);width:18px;height:18px;stroke:#111;fill:none;stroke-width:2}
.s-clear{position:absolute;right:46px;top:50%;transform:translateY(-50%);font-size:15px;color:#111;padding:6px}
.s-go{position:absolute;right:12px;top:50%;transform:translateY(-50%);width:22px;height:22px}
.s-go svg{width:20px;height:20px;stroke:#111;fill:none;stroke-width:2}
.suggest{position:absolute;top:54px;left:0;right:0;background:#fff;border-radius:8px;box-shadow:0 8px 30px rgba(0,0,0,.18);padding:12px 0;z-index:300;max-height:420px;overflow:auto}
.sg-item{display:flex;align-items:center;gap:12px;padding:9px 20px;cursor:pointer;font-size:14px}
.sg-item:hover{background:#f5f5f5}
.sg-item svg{width:15px;height:15px;stroke:#484848;fill:none;stroke-width:2;flex:0 0 auto}
.sg-head{padding:10px 20px 4px;font-size:12px;color:#6f6f6f;font-weight:700;text-transform:uppercase;letter-spacing:.04em}
.sg-prod{display:flex;gap:14px;align-items:center;padding:8px 20px;cursor:pointer}
.sg-prod:hover{background:#f5f5f5}
.sg-prod img{width:56px;height:42px;object-fit:contain;background:#f7f7f7}
.sg-prod .p{font-weight:700}
.head-right{display:flex;align-items:center;gap:26px;margin-left:auto}
.login{display:flex;align-items:center;gap:8px;font-size:14px;white-space:nowrap;cursor:pointer}
.login:hover{text-decoration:underline}
.icon-btn{position:relative;width:24px;height:24px;display:inline-flex;align-items:center;justify-content:center}
.icon-btn svg{width:24px;height:24px;stroke:#111;fill:none;stroke-width:1.5}
.icon-btn.faved svg{fill:#111}
.badge{position:absolute;top:-7px;right:-9px;background:#0058a3;color:#fff;font-size:11px;font-weight:700;min-width:17px;height:17px;border-radius:999px;display:flex;align-items:center;justify-content:center;padding:0 4px}

/* ---------- mega menu ---------- */
#headwrap{position:relative;z-index:110;background:#fff}
.mega{position:absolute;top:100%;left:0;right:0;background:#fff;box-shadow:0 20px 40px rgba(0,0,0,.18);padding:26px 48px 40px;display:none}
.mega.open{display:block}
.mega-tabs{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:34px}
.mega-tab{border:1px solid #cfcfcf;border-radius:6px;padding:14px 22px;font-weight:700;font-size:14px;background:#fff;white-space:nowrap}
.mega-tab.on{border:2px solid #0058a3;padding:13px 21px}
.mega-body{display:grid;grid-template-columns:230px 220px 220px 1fr 300px;gap:40px}
.mega-col a{display:block;padding:5px 0;font-size:14px}
.mega-col a:hover{text-decoration:underline}
.mega-col.big a{font-size:19px;font-weight:700;padding:7px 0;line-height:1.3}
.mega-col h5{font-size:14px;color:#111;margin-bottom:10px;font-weight:700}
.mega-promo{border-radius:4px;overflow:hidden;background:#e0400a;color:#fff;cursor:pointer}
.mega-promo img{width:100%;height:170px;object-fit:cover}
.mega-promo .mp-t{padding:20px;font-size:19px;font-weight:700;line-height:1.35}

/* ---------- home ---------- */
.pills{display:flex;gap:12px;padding:18px 48px 6px;overflow-x:auto}
.pill{display:flex;align-items:center;gap:10px;background:#f5f5f5;border-radius:999px;padding:12px 22px;font-weight:700;font-size:14px;white-space:nowrap;cursor:pointer;flex:0 0 auto}
.pill:hover{background:#eaeaea}
.pill img{width:26px;height:26px;object-fit:contain;border-radius:4px}
.hero{display:grid;grid-template-columns:1.02fr 1fr;gap:12px;padding:18px 48px 8px}
.hero-big{position:relative;border-radius:2px;overflow:hidden;min-height:560px}
.hero-big img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0}
.hero-r{display:grid;grid-template-rows:1.35fr 1fr;gap:12px}
.hero-tile{position:relative;overflow:hidden;border-radius:2px;cursor:pointer}
.hero-tile img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0}
.hero-b{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.tag-fam{position:absolute;top:20px;left:20px;background:#0076c1;color:#fff;font-size:12px;font-weight:700;padding:5px 9px;z-index:2}
.tag-new{position:absolute;top:20px;left:20px;background:#e00751;color:#fff;font-size:12px;font-weight:700;padding:5px 9px;z-index:2;background:#d43a00}
.pause-btn{position:absolute;top:20px;right:20px;width:44px;height:44px;border-radius:50%;background:rgba(17,17,17,.8);display:flex;align-items:center;justify-content:center;z-index:2}
.pause-btn svg{width:14px;height:14px;fill:#fff;stroke:none}
.hero-cap{position:absolute;left:0;right:0;bottom:0;padding:22px;color:#fff;font-size:24px;font-weight:700;display:flex;justify-content:space-between;align-items:center;background:linear-gradient(transparent,rgba(0,0,0,.35));z-index:2}
.hero-cap svg{width:30px;height:30px;stroke:#fff;fill:none;stroke-width:2}
.home-sec{padding:44px 48px}
.home-sec h2{font-size:24px;margin-bottom:22px}
.series-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.series-tile{cursor:pointer}
.series-tile img{width:100%;aspect-ratio:4/3;object-fit:cover;background:#f5f5f5}
.series-tile .st-t{padding:12px 0;font-weight:700;font-size:15px}
.series-tile:hover .st-t{text-decoration:underline}

/* ---------- cookie ---------- */
.cookie{position:fixed;left:0;right:0;bottom:0;background:#fff;border-top:1px solid #dfdfdf;padding:16px 48px;display:flex;align-items:center;justify-content:space-between;gap:40px;z-index:800;box-shadow:0 -4px 20px rgba(0,0,0,.06)}
.cookie p{font-size:13px;max-width:820px}
.cookie a{text-decoration:underline;font-weight:700}
.cookie-btns{display:flex;gap:12px;flex:0 0 auto}
.btn-dark{background:#111;color:#fff;border-radius:999px;padding:12px 26px;font-weight:700;font-size:13px}
.btn-dark:hover{background:#333}

/* ---------- listing ---------- */
.help-banner{border-left:3px solid #0058a3;background:#f5f5f5;padding:18px 24px;margin:18px 48px 0;font-size:14px}
.list-head{display:flex;justify-content:space-between;align-items:flex-start;gap:40px;padding:26px 48px 8px}
.list-head h1{font-size:24px;font-weight:700}
.design-card{border:1px solid #929292;border-radius:2px;padding:20px 26px;display:flex;gap:16px;align-items:flex-start;min-width:420px;cursor:pointer}
.design-card b{font-size:15px;display:block}
.design-card u{font-size:13px}
.design-card svg{width:22px;height:22px;stroke:#111;fill:none;stroke-width:1.6;margin-top:3px}
.list-body{display:flex;gap:56px;padding:0 48px 60px;align-items:flex-start}
.facets{flex:0 0 250px;padding-top:8px}
.facet{border-top:1px solid #dfdfdf}
.facet:last-child{border-bottom:1px solid #dfdfdf}
.facet-head{width:100%;display:flex;justify-content:space-between;align-items:center;padding:15px 0;font-weight:700;font-size:14px;background:none;border:none;cursor:pointer}
.facet-head svg{width:14px;height:14px;stroke:#111;fill:none;stroke-width:2;transition:transform .15s}
.facet.open .facet-head svg{transform:rotate(180deg)}
.facet-head .fh-count{font-weight:400;color:#6f6f6f;margin-left:auto;margin-right:10px}
.facet-head .fh-box{width:16px;height:16px;border:1.5px solid #929292;border-radius:2px;display:inline-block}
.facet-body{padding:4px 0 18px;display:none}
.facet.open .facet-body{display:block}
.sort-opt{display:flex;align-items:center;justify-content:space-between;padding:9px 0;cursor:pointer;font-size:14px}
.sort-opt input{appearance:none;width:20px;height:20px;border:1.5px solid #929292;border-radius:50%;cursor:pointer;flex:0 0 auto}
.sort-opt input:checked{border:6px solid #111}
.facet-placeholder{color:#929292;font-size:13px;padding:6px 0}
.facet-placeholder .ph-row{display:flex;justify-content:space-between;padding:7px 0;color:#9a9a9a}
.facet-placeholder .ph-box{width:16px;height:16px;border:1.5px solid #cfcfcf;border-radius:2px}
.swatches{display:grid;grid-template-columns:1fr 1fr;gap:18px 8px;padding-top:8px}
.swatch{display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer;font-size:13px}
.swatch .swc{width:58px;height:58px;border-radius:50%;border:1px solid #dfdfdf}
.swatch .cnt{color:#6f6f6f;font-size:13px}
.swatch.on .swc{box-shadow:0 0 0 2px #fff,0 0 0 4px #111}
.swatch.dis{cursor:default}
.list-main{flex:1;min-width:0}
.chips{display:flex;gap:10px;padding:8px 0 4px}
.chip{background:#f5f5f5;border-radius:999px;padding:8px 16px;font-size:13px;font-weight:700;display:flex;gap:10px;align-items:center;cursor:pointer}
.cmp-bar{display:flex;justify-content:space-between;align-items:center;padding:14px 0 6px}
.cmp-close{font-size:14px;cursor:pointer}
.cmp-close:hover{text-decoration:underline}
.cmp-right{display:flex;align-items:center;gap:16px}
.cmp-thumbs{display:flex;gap:6px}
.cmp-thumbs img{width:44px;height:34px;object-fit:contain;background:#f5f5f5;border:1px solid #e5e5e5}
.btn-blackpill{background:#111;color:#fff;border-radius:999px;padding:14px 30px;font-weight:700;font-size:14px}
.btn-blackpill:hover{background:#333}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:44px 24px;padding-top:14px}
.card{position:relative;min-width:0}
.card-img{position:relative;background:#fff;cursor:pointer}
.card-img img{width:100%;aspect-ratio:5/4;object-fit:contain}
.badge-best{position:absolute;top:0;left:0;background:#e00751;color:#fff;font-size:12px;font-weight:700;padding:5px 9px;z-index:2}
.heart{position:absolute;bottom:12px;right:12px;width:38px;height:38px;background:#fff;border-radius:50%;box-shadow:0 1px 6px rgba(0,0,0,.15);display:flex;align-items:center;justify-content:center;z-index:2}
.heart svg{width:19px;height:19px;stroke:#111;fill:none;stroke-width:1.6}
.heart.on svg{fill:#111}
.cmp{display:flex;align-items:center;gap:10px;font-size:14px;color:#484848;margin:2px 0 10px;cursor:pointer;user-select:none}
.cmp input{appearance:none;width:18px;height:18px;border:1.5px solid #929292;border-radius:3px;cursor:pointer;position:relative;flex:0 0 auto}
.cmp input:checked{background:#111;border-color:#111}
.cmp input:checked::after{content:"";position:absolute;left:5px;top:1.5px;width:4px;height:9px;border:solid #fff;border-width:0 2px 2px 0;transform:rotate(45deg)}
.fam-label{color:#0076c1;font-weight:700;font-size:13px;margin-bottom:2px}
.card-name{font-weight:700;font-size:14px;cursor:pointer;display:inline-block}
.card-name:hover{text-decoration:underline}
.card-desc{font-size:14px;color:#111;margin-top:1px}
.price-row{display:flex;justify-content:space-between;align-items:flex-start;margin-top:6px}
.price{font-size:22px;font-weight:700;letter-spacing:-.01em}
.price .pk{font-size:14px;font-weight:400}
.price.blue{color:#0058a3}
.cart-btn{width:44px;height:44px;border-radius:50%;background:#0058a3;display:flex;align-items:center;justify-content:center;flex:0 0 auto}
.cart-btn:hover{background:#004f93}
.cart-btn svg{width:20px;height:20px;stroke:#fff;fill:none;stroke-width:1.8}
.save-line{color:#0076c1;font-weight:700;font-size:13px;margin-top:2px}
.reg-line{font-size:12px;color:#484848;margin-top:6px}
.valid-line{font-size:12px;color:#484848}
.rating-row{display:flex;align-items:center;gap:8px;margin-top:8px;font-size:13px}
.rating-row .rc{text-decoration:underline;color:#484848}
.stars{display:inline-flex;gap:1px}
.more-opt{font-size:13px;margin-top:6px;color:#111}

/* ---------- compare page ---------- */
.page-pad{padding:26px 48px 80px}
.page-pad h1{font-size:36px;margin-bottom:40px}
.compare-cards{display:flex;gap:24px;flex-wrap:wrap}
.compare-card{width:330px;position:relative}
.rm-btn{font-size:20px;color:#929292;padding:6px;margin-left:-6px;display:block}
.rm-btn:hover{color:#111}
.kf-title{font-size:18px;font-weight:700;margin:44px 0 14px}
.kf-row{display:flex;gap:24px;background:#f5f5f5;margin-bottom:6px}
.kf-row:nth-child(even){background:#fff}
.kf-cell{width:330px;padding:18px 20px;flex:0 0 auto}
.kf-cell b{display:block;font-size:14px;margin-bottom:2px}
.empty-note{padding:40px 0;font-size:16px}
.empty-note a{color:#0058a3;text-decoration:underline}

/* ---------- PDP ---------- */
.crumbs{padding:18px 48px 6px;font-size:13px;color:#484848;display:flex;flex-wrap:wrap;gap:6px}
.crumbs a:hover{text-decoration:underline}
.crumbs .sep{color:#929292}
.crumbs .cur{color:#111}
.pdp{display:grid;grid-template-columns:84px minmax(0,648px) minmax(0,1fr);gap:28px;padding:12px 48px 30px;align-items:start}
.thumbs{display:flex;flex-direction:column;gap:10px}
.thumb{width:84px;height:64px;border:1px solid #e0e0e0;cursor:pointer;position:relative;background:#f7f7f7}
.thumb img{width:100%;height:100%;object-fit:contain}
.thumb.on{border:2px solid #111}
.thumb .playb{position:absolute;inset:0;display:flex;align-items:center;justify-content:center}
.thumb .playb span{width:24px;height:24px;border-radius:50%;background:rgba(17,17,17,.75);display:flex;align-items:center;justify-content:center}
.thumb .playb svg{width:10px;height:10px;fill:#fff}
.main-img{position:relative;background:#f7f7f7}
.main-img img{width:100%;aspect-ratio:1/1;object-fit:contain;cursor:pointer}
.media-btns{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);display:flex;gap:12px}
.pill-dark{background:rgba(17,17,17,.88);color:#fff;border-radius:999px;padding:12px 22px;font-weight:700;font-size:13px;display:flex;align-items:center;gap:9px}
.pill-dark svg{width:16px;height:16px;stroke:#fff;fill:none;stroke-width:1.7}
.pill-dark:hover{background:#111}
.pdp-info{padding-top:26px;max-width:520px}
.pdp-title{font-size:16px;font-weight:700;margin-top:2px}
.pdp-desc{font-size:14px;margin-top:1px}
.pdp-price{margin-top:12px;font-size:26px;font-weight:700;color:#0058a3}
.pdp-price .pk{font-size:15px;font-weight:400}
.pdp-fav{position:absolute;top:0;right:0}
.info-wrap{position:relative}
.pdp-save{color:#0076c1;font-weight:700;font-size:14px;margin-top:2px}
.pdp-reg{font-size:13px;color:#111;margin-top:8px}
.pdp-valid{font-size:13px;color:#484848}
.pdp-rating{display:flex;align-items:center;gap:8px;margin-top:10px;cursor:pointer}
.pdp-rating .rc{text-decoration:underline;font-size:13px}
.note-row{display:flex;gap:10px;align-items:center;margin:18px 0;font-size:14px;color:#111}
.note-row svg{width:18px;height:18px;stroke:#484848;fill:none;stroke-width:1.6;flex:0 0 auto}
.sec-label{font-weight:700;font-size:14px;margin:20px 0 4px}
.sec-sub{font-size:13px;margin-bottom:12px}
.sw-grid{display:flex;flex-wrap:wrap;gap:10px;padding-bottom:22px;border-bottom:1px solid #dfdfdf}
.sw{width:64px;height:64px;border:1px solid #e0e0e0;border-radius:6px;overflow:hidden;cursor:pointer;padding:2px;background:#f7f7f7}
.sw img{width:100%;height:100%;object-fit:contain}
.sw.on{border:2px solid #111;box-shadow:0 0 0 1px #fff inset}
.sw.dis{cursor:default}
.sw-more{width:64px;height:64px;border:1px solid #cfcfcf;border-radius:6px;display:flex;align-items:center;justify-content:center;font-weight:700;color:#484848;cursor:default;background:#fff}
.diy{display:flex;justify-content:space-between;align-items:flex-start;padding:20px 0;border-bottom:1px solid #dfdfdf;cursor:pointer}
.diy b{font-size:14px;display:block}
.diy span{font-size:13px;color:#484848}
.diy svg{width:18px;height:18px;stroke:#111;fill:none;stroke-width:1.7;flex:0 0 auto;margin-top:2px}
.howto{padding:20px 0 6px}
.howto .sec-label{margin:0 0 10px}
.avail-row{display:flex;gap:14px;padding:9px 0;align-items:flex-start;font-size:14px}
.avail-row svg{width:22px;height:22px;stroke:#111;fill:none;stroke-width:1.5;flex:0 0 auto;margin-top:1px}
.dot-g{display:inline-block;width:11px;height:11px;border-radius:50%;background:#0a8a00;margin-right:8px;vertical-align:-1px}
.dot-ga{display:inline-block;width:11px;height:11px;border-radius:50%;background:#cfcfcf;margin-right:8px;vertical-align:-1px}
.avail-row a{text-decoration:underline;font-weight:700}
.avail-row .sub{font-size:13px;color:#111;margin-top:2px}
.check-avail{display:flex;gap:10px;align-items:center;color:#111;padding:6px 0;cursor:pointer}
.check-avail u{font-size:14px}
.add-btn{width:100%;background:#0058a3;color:#fff;border-radius:999px;height:56px;font-size:15px;font-weight:700;margin:16px 0 18px}
.add-btn:hover{background:#004f93}
.buy-row{display:flex;gap:14px;margin:16px 0 18px}
.buy-row .add-btn{margin:0;flex:1}
.qty-stepper{display:flex;align-items:center;border:1px solid #929292;border-radius:999px;height:56px;padding:0 6px;flex:0 0 auto}
.qty-stepper button{width:40px;height:44px;font-size:20px;color:#111;display:flex;align-items:center;justify-content:center}
.qty-stepper button.dis{color:#c5c5c5;cursor:default}
.qty-stepper .qv{min-width:30px;text-align:center;font-size:15px}
.service-box{background:#f5f5f5;border-radius:8px;padding:16px 18px;display:flex;gap:14px;margin:6px 0 16px;font-size:14px;align-items:flex-start}
.service-box svg{width:22px;height:22px;stroke:#111;fill:none;stroke-width:1.5;flex:0 0 auto}
.service-box a{text-decoration:underline}
.points-box{display:flex;gap:14px;padding:14px 0;align-items:flex-start}
