.disc-head .dl span{font-size:14px}
.disc-head svg{width:14px;height:14px;stroke:#111;fill:none;stroke-width:2;transition:transform .15s}
.disc.open .disc-head svg{transform:rotate(180deg)}
.disc-body{display:none;padding-top:18px}
.disc.open .disc-body{display:block}
.disc-row{display:flex;gap:14px}
.disc-row input{flex:1;height:48px;border:1.5px solid #929292;border-radius:4px;padding:0 16px;font-size:15px;outline:none}
.disc-row input:focus{border-color:#0058a3;box-shadow:0 0 0 1px #0058a3}
.disc-row input.err{border-color:#e00751;box-shadow:0 0 0 1px #e00751}
.disc-row .btn-dark{padding:0 34px;height:48px}
.disc-err{color:#e00751;font-size:13px;margin-top:8px;display:flex;gap:8px;align-items:center}
.disc-err svg{width:16px;height:16px;fill:#e00751}
.disc-note{font-size:13px;color:#484848;margin-top:12px}
.checkout-btn{width:100%;background:#0058a3;color:#fff;border-radius:999px;height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 12px 0 36px;font-size:16px;font-weight:700;margin:22px 0 18px}
.checkout-btn:hover{background:#004f93}
.checkout-btn .arr{width:44px;height:44px;border-radius:50%;background:#fff;display:flex;align-items:center;justify-content:center}
.checkout-btn .arr svg{width:20px;height:20px;stroke:#0058a3;fill:none;stroke-width:2.2}
.pay-icons{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:6px 0 20px}
.pay-icons img{height:24px;width:auto}
.fam-deliv{background:#eaf4fc;border-radius:8px;padding:16px 20px;display:flex;gap:14px;align-items:flex-start;font-size:14px;margin-bottom:16px}
.fam-deliv svg{width:22px;height:22px;stroke:#111;fill:none;stroke-width:1.6;flex:0 0 auto}
.fam-deliv a{text-decoration:underline}
.ret-link{font-size:13px;text-decoration:underline;display:inline-block;margin-bottom:10px}
.ess-wrap{padding:30px 88px 70px;border-top:1px solid #e5e5e5}
.ess-wrap h2{font-size:24px;margin-bottom:24px}
.ess-row{display:grid;grid-template-columns:repeat(5,1fr);border:1px solid #e5e5e5}
.ess-card{padding:22px;border-right:1px solid #e5e5e5;position:relative;min-width:0}
.ess-card:last-child{border-right:none}
.ess-card img{width:100%;aspect-ratio:1/1;object-fit:contain}
.ess-card .en{font-weight:700;font-size:14px;margin-top:14px}
.ess-card .ed{font-size:13px;color:#484848;min-height:36px}
.ess-card .ep{font-size:20px;font-weight:700;margin-top:6px;display:inline-block}
.ess-card .ep.yellow{background:#ffdb00;padding:2px 8px}
.ess-card .cart-btn{position:absolute;bottom:80px;left:22px;width:42px;height:42px}
.ess-card .ea{margin-top:40px;font-size:12px}
.ess-card .ea div{display:flex;gap:8px;align-items:center;padding:2px 0}
.ess-card .ea .d{width:9px;height:9px;border-radius:50%;background:#0a8a00}
.bag-empty{padding:60px 0}
.bag-empty p{font-size:16px;margin-bottom:22px}

/* ---------- toast ---------- */
#toast-root{position:fixed;top:70px;right:28px;z-index:1300;display:flex;flex-direction:column;gap:10px}
.toast{background:#111;color:#fff;border-radius:8px;padding:16px 20px;display:flex;gap:22px;align-items:center;font-size:14px;box-shadow:0 10px 30px rgba(0,0,0,.3);max-width:400px;animation:fadein .18s ease}
.toast a{color:#fff;font-weight:700;text-decoration:underline;cursor:pointer;white-space:nowrap}
.toast .tx{cursor:pointer;font-size:16px;padding:4px}

/* ---------- footer ---------- */
.footer{background:#f5f5f5;margin-top:40px;padding:44px 48px 30px}
.footer-cols{display:grid;grid-template-columns:repeat(4,1fr);gap:30px;padding-bottom:34px;border-bottom:1px solid #dfdfdf}
.footer-cols h5{font-size:14px;margin-bottom:14px}
.footer-cols a{display:block;font-size:13px;color:#484848;padding:4px 0}
.footer-cols a:hover{text-decoration:underline;color:#111}
.footer-bottom{display:flex;justify-content:space-between;align-items:center;padding-top:24px;flex-wrap:wrap;gap:16px}
.footer-bottom .pay-icons{padding:0}
.footer-bottom p{font-size:12px;color:#6f6f6f}
@media (max-width:1100px){.grid{grid-template-columns:repeat(3,1fr)}.pdp{grid-template-columns:84px 1fr;}.pdp-info{grid-column:2}.bag-wrap{grid-template-columns:1fr;padding:30px 40px}.ess-wrap{padding:30px 40px}}
