/* ---------------- bag helpers ---------------- */
function bagCount(){ return S.bag.reduce((a,i)=>a+i.qty,0); }
function bagTotals(){
  let products=0, saveFam=0, asmRaw=0;
  S.bag.forEach(i=>{ products += i.regular*i.qty; saveFam += (i.regular-i.member)*i.qty; if(i.asm && i.asmFee) asmRaw += i.asmFee*i.qty; });
  const asm = asmRaw>0 ? Math.max(asmRaw, 52) : 0;
  return { products, asm, total: products+asm, saveFam, points: Math.round(products) };
}
function snapshotOf(item){
  let desc = item.description || item.desc || '';
  if(item.pack_size) desc += ', '+item.pack_size+' pack/pack';
  if(item.desc && !item.description) desc = item.desc;
  return { id:item.id, route:item.route||null, name:item.name, desc, img:item.image||item.img,
    regular:item.regular_price!=null?item.regular_price:item.regular,
    member:item.member_price!=null?item.member_price:item.member,
    asmFee:item.assembly_per_unit||0, isCombo:!!item.components };
}
function addToBag(item, qty){
  const snap = snapshotOf(item);
  const ex = S.bag.find(i=>String(i.id)===String(snap.id));
  if(ex) ex.qty = Math.min(99, ex.qty+qty); else S.bag.push(Object.assign({qty, asm:false}, snap));
  save(); updateBadge();
}

/* ---------------- routing ---------------- */
function parseHash(){
  let h = location.hash.slice(1);
  if(!h) h = '/us/en/';
  const qi = h.indexOf('?');
  const p = qi>=0 ? h.slice(0,qi) : h;
  const qs = qi>=0 ? h.slice(qi+1) : '';
  return { path:p, params:new URLSearchParams(qs) };
}
function go(path){ if(location.hash === '#'+path){ renderApp(); } else location.hash = path; }
window.addEventListener('hashchange', ()=>{ closeOverlays(); renderApp(); });

function renderApp(){
  CUR = parseHash();
  document.getElementById('app').innerHTML =
    '<div id="headwrap">'+headerHTML()+'</div><main id="page">'+pageHTML(CUR.path, CUR.params)+'</main>'+footerHTML()+cookieHTML();
  window.scrollTo(0,0);
}
function renderHead(){ const w=$('#headwrap'); if(w) w.innerHTML = headerHTML(); }
function renderCurrentPage(){ CUR = parseHash(); const p=$('#page'); if(p) p.innerHTML = pageHTML(CUR.path, CUR.params); }
function updateBadge(){
  const b = $('#bag-badge'); const n = bagCount();
  if(b){ if(n>0){ b.textContent=n; b.classList.remove('hidden'); } else b.classList.add('hidden'); }
}
function pageHTML(path, params){
  if(path==='/' || path==='/us/en' || path==='/us/en/') return homeHTML();
  if(path.indexOf('/us/en/search')===0) return searchHTML(params);
  if(path.indexOf('/us/en/compare')===0) return compareHTML();
  if(path.indexOf('/us/en/bag')===0) return bagHTML();
  if(path.indexOf('/us/en/p/')===0) return pdpHTML(path);
  return '<div class="page-pad"><h1>Page not found</h1><p class="empty-note">This page is not part of the recorded slice. <a data-nav="/us/en/">Back to homepage</a></p></div>';
}

