/* ---------------- listing ---------------- */
function isWhite(it){ return (String(it.color)+' '+it.description+' '+it.route).toLowerCase().indexOf('white')>=0; }
function searchItems(params){
  const q = (params.get('q')||'').toLowerCase();
  let items = CAT.catalog.filter(it=> !q || (it.name+' '+it.description+' '+it.route).toLowerCase().indexOf(q)>=0);
  if(params.get('color')==='white') items = items.filter(isWhite);
  const sort = params.get('sort')||'best';
  if(sort==='price-asc') items = items.slice().sort((a,b)=>a.member_price-b.member_price);
  else if(sort==='price-desc') items = items.slice().sort((a,b)=>b.member_price-a.member_price);
  else if(sort==='rating') items = items.slice().sort((a,b)=>(b.rating||0)-(a.rating||0));
  else if(sort==='name') items = items.slice().sort((a,b)=>(a.name+a.description).localeCompare(b.name+b.description));
  return items;
}
function searchURL(q, color, sort){
  let u = '/us/en/search/?q='+encodeURIComponent(q||'');
  if(color) u += '&color='+color;
  if(sort && sort!=='best') u += '&sort='+sort;
  return u;
}
function facetRow(key, label, body, extra){
  const open = ui.facets.has(key);
  return '<div class="facet'+(open?' open':'')+'"><button class="facet-head" data-action="facet" data-f="'+key+'"><span>'+label+'</span>'+(extra||'')+I.chevD+'</button>'
  + '<div class="facet-body">'+body+'</div></div>';
}
function placeholderFacet(key,label,rows){
  return facetRow(key,label,'<div class="facet-placeholder">'+rows.map(r=>'<div class="ph-row"><span>'+r[0]+'</span><span>'+r[1]+'</span></div>').join('')+'</div>');
}
