function pdpHTML(path){
  const item = findByRoute(path);
  if(!item) return '<div class="page-pad"><h1>Product not found</h1><p class="empty-note">This product is not part of the recorded catalog slice. <a data-nav="/us/en/search/?q=besta">Back to search</a></p></div>';
  document.title = item.name+' '+item.description.slice(0,40)+' - IKEA';
  const isCombo = !!item.components;
  const isLeg = item.id==='20293568';
  /* breadcrumbs */
  let crumbs;
  if(isLeg) crumbs = ['Products','Storage & organization','Storage solution systems','BESTÅ storage system','BESTÅ all parts & accessories','BESTÅ legs','STUBBARP Leg'];
  else if(item.name==='STUBBARP') crumbs = ['Products','Storage & organization','Storage solution systems','BESTÅ storage system','BESTÅ all parts & accessories','BESTÅ legs','STUBBARP Leg'];
  else if(isCombo) crumbs = ['Products','Storage & organization','Storage solution systems','BESTÅ storage system','BESTÅ sideboards','BESTÅ Storage combination with doors'];
  else crumbs = ['Products','Storage & organization','Storage solution systems','BESTÅ storage system','BESTÅ frames',item.name+' '+item.description.split(',')[0]];
  let info = '<div class="pdp-info info-wrap">'+priceBlockPDP(item,{suffix:isLeg?'/2 pack':''});
  if(isCombo){
    info += '<div class="note-row">'+I.info+'<span>Knobs and handles are sold separately.</span></div>';
    info += '<div class="sec-label">Choose color</div><div class="sec-sub">'+esc(item.color)+'</div>';
    info += swatchesHTML(COMBO_SW, item.image);
    info += '<div class="diy"><span><b>Design it yourself</b><span>Customise BESTÅ in our planning tool</span></span>'+I.ext+'</div>';
    info += howtoHTML();
    info += '<button class="add-btn" data-action="pdp-add" data-id="'+item.id+'">Add to bag</button>';
    info += '<div class="service-box">'+I.wrench+'<span>Have your BESTÅ professionally assembled for <b>'+money(item.assembly_per_unit)+'</b>. <a>Learn more</a></span></div>';
    info += pointsHTML(Math.round(item.member_price)) + mindHTML() + payBoxHTML(item.member_price);
  } else if(isLeg){
    info += '<div class="note-row">'+I.info+'<span>BESTÅ supporting leg sold separately.</span></div>';
    info += '<div class="sec-label">Choose color</div><div class="sec-sub">White stained oak effect</div>';
    info += '<div class="sw-grid">'+LEG_SW.map(s=> s.route ? '<a class="sw'+(s.img===item.image?' on':'')+'" data-nav="'+s.route+'"><img src="'+s.img+'" alt=""></a>' : '<span class="sw dis"><img src="'+s.img+'" alt=""></span>').join('')+'</div>';
    info += howtoHTML();
    info += '<div class="buy-row">'+stepperHTML(item)+addBtnHTML(item)+'</div>';
    info += pointsHTML(Math.round(item.member_price)) + mindHTML();
  } else {
    info += '<div class="note-row">'+I.info+'<span>Sold separately: knobs, handles and suspension rail.</span></div>';
    info += howtoHTML();
    info += '<div class="buy-row">'+stepperHTML(item)+addBtnHTML(item)+'</div>';
    info += pointsHTML(Math.round(item.member_price)) + mindHTML();
  }
  info += '</div>';
  let lower = '';
  if(isCombo){
    lower = tabsHTML(true)
    + '<div class="pdp-sec" id="sec-overview"><p class="lead">BESTÅ storage system lets you create exactly the solution you need – the frames, doors, drawers and interior organizers can be combined in almost endless ways, and you can change or add to your solution whenever you like.</p></div>'
    + '<div class="pdp-sec" id="sec-details"><div class="acc open"><button class="acc-head" data-action="acc-toggle">Product details '+I.chevD+'</button><div class="acc-body"><table class="meas-table"><tr><td class="k">Article number</td><td class="v">'+artNo(item.id)+'</td></tr><tr><td class="k">Color</td><td class="v">'+esc(item.color)+'</td></tr><tr><td class="k">Care instructions</td><td class="v">Wipe clean with a damp cloth</td></tr></table></div></div></div>'
    + measSectionHTML() + includedHTML(item) + revSectionHTML(item) + accessoriesHTML();
  } else {
    lower = revSectionHTML(item) + (item.name.indexOf('BESTÅ')>=0 ? accessoriesHTML() : '');
  }
  return crumbsHTML(crumbs) + '<div class="pdp">'+galleryHTML(item)+info+'</div>' + lower;
}

