function saveZip(){
  const i = $('#zip-input'); const hint = $('#zip-hint');
  const v = (i.value||'').trim();
  if(!/^\d{5}$/.test(v)){
    i.classList.remove('ok'); i.classList.add('err');
    hint.className='zip-hint err'; hint.textContent='Enter a valid ZIP code.';
    return;
  }
  S.zip = v; save(); closeOverlays(); renderHead(); renderCurrentPage();
  if(!S.store) openStore();
}
