/* reviews modal */
function openReviews(item){
  ui.rev = { id:item.id, sort:'recent', topic:'all', stars:new Set(), hidden:false, sortOpen:false };
  renderReviews(item);
}
function reviewDate(r){ const p=r.d.split('/'); return (+p[2])*10000+(+p[0])*100+(+p[1]); }
function renderReviews(item){
  const st = ui.rev;
  const rating = item.rating||3.7, count = item.review_count||123;
  let list = REVIEWS.slice();
  if(st.topic!=='all') list = list.filter(r=>r.tags.indexOf(st.topic)>=0);
  if(st.stars.size) list = list.filter(r=>st.stars.has(r.r));
  if(st.sort==='recent') list.sort((a,b)=>reviewDate(b)-reviewDate(a));
  else if(st.sort==='oldest') list.sort((a,b)=>reviewDate(a)-reviewDate(b));
  else if(st.sort==='high') list.sort((a,b)=>b.r-a.r);
  else if(st.sort==='low') list.sort((a,b)=>a.r-b.r);
  else if(st.sort==='helpful') list.sort((a,b)=>b.h-a.h);
  const bars = REV_BARS.map(b=>{
    const c = Math.round(b[1]/123*count);
    return '<div class="bar-row"><span class="n">'+b[0]+'</span>'+starSVG(1)+'<span class="bar"><i style="width:'+(b[1]/54*100)+'%"></i></span><span class="c">'+c+'</span></div>';
  }).join('');
  const aspects = REV_ASPECTS.map(a=>{
    const filled = Math.round(a[1]); let dots='';
    for(let i=1;i<=5;i++) dots += '<i'+(i<=filled?'':' class="e"')+'></i>';
    return '<div class="aspect"><span class="a-n">'+a[0]+'</span><span><span class="dot5">'+dots+'</span>'+a[1].toFixed(1)+'</span></div>';
  }).join('');
  const sortPop = st.sortOpen ? '<div class="sort-pop">'+[['recent','Most recent'],['oldest','Oldest'],['high','Highest rated'],['low','Lowest rated'],['helpful','Most helpful']].map(o=>'<label><input type="radio" name="rev-sort" value="'+o[0]+'"'+(st.sort===o[0]?' checked':'')+'>'+o[1]+'</label>').join('')+'</div>' : '';
  const summary = st.hidden ? '' : '<p>BESTÅ offers a stylish design that enhances many spaces. Customers often report issues with overall stability and quality. They mention wobbly structures and difficulty aligning or securing doors. Assembling the door components often proves difficult, impacting functionality. BESTÅ provides a modern, adaptable look for living spaces.</p>';
  const items = list.map(r=>{
    return '<div class="rev-item"><div class="ri-h">'+stars(r.r)+'<span>'+r.d+'</span></div>'
    + '<h4>'+esc(r.t)+'</h4><p>'+esc(r.b)+'</p><span class="author-chip">'+esc(r.a)+'</span>'
    + '<div class="ri-f"><span class="rep">Report</span><button class="helpful">Helpful? ('+r.h+')</button></div>'
    + (r.resp?'<div class="ikea-resp"><b>Response from IKEA:</b> · '+r.rd+'<p>'+esc(r.resp)+'</p></div>':'')
    + '</div>';
  }).join('');
  overlayRoot().innerHTML = scrimHTML()
  + '<div class="rev"><button class="rev-x" data-action="close-overlays">✕</button>'
  + '<div class="rev-left"><div class="big">'+rating+'</div>'+stars(rating)+'<div class="based">Based on '+count+' reviews</div>'
  + bars + '<div style="margin-top:26px">'+aspects+'</div>'
  + '<button class="btn-outline" data-action="write-review">Write a review</button></div>'
  + '<div class="rev-right"><h2>Customer reviews</h2>'
  + '<div class="rev-tools"><button class="tool-btn" data-action="rev-filter">'+I.filter+'Filter</button>'
  + '<button class="tool-btn'+(st.sortOpen?' on':'')+'" data-action="rev-sort-btn">'+I.sort+'Sort by</button>'+sortPop+'</div>'
  + '<div class="rev-tabs"><span class="rev-tab on">United States</span><span class="rev-tab">Other countries</span></div>'
  + '<div class="rev-summary"><div class="rs-h"><b>Reviews summary <span class="ai">AI</span></b><a data-action="rev-summary">'+(st.hidden?'Show summary':'Hide summary')+'</a></div>'
  + summary
  + '<div class="rs-f"><span>AI-generated summary of actual customer reviews.</span><span class="help">Helpful? <svg viewBox="0 0 24 24"><path d="M7 11v9H4v-9h3zm1 0l4.5-7c1 0 1.8.8 1.5 1.8L13.5 9H20a2 2 0 012 2.3l-1.2 6A2 2 0 0118.8 19H8v-8z"/></svg><svg viewBox="0 0 24 24" style="transform:rotate(180deg)"><path d="M7 11v9H4v-9h3zm1 0l4.5-7c1 0 1.8.8 1.5 1.8L13.5 9H20a2 2 0 012 2.3l-1.2 6A2 2 0 0118.8 19H8v-8z"/></svg></span></div></div>'
  + '<div style="font-weight:700;font-size:14px;margin-bottom:10px">Topics <span class="ai" style="font-size:11px;border:1px solid #929292;border-radius:3px;padding:1px 4px">AI</span></div>'
  + '<div class="topics"><span class="topic-chip'+(st.topic==='all'?' on':'')+'" data-action="rev-topic" data-t="all">Show all</span>'
  + REV_TOPICS.map(t=>'<span class="topic-chip'+(st.topic===t?' on':'')+'" data-action="rev-topic" data-t="'+esc(t)+'">'+esc(t)+'</span>').join('')+'</div>'
  + (list.length?items:'<p class="muted" style="padding:30px 0">No reviews match the selected filters.</p>')
  + '</div></div>';
}

/* toast */
function showToast(msg, undo){
  const root = document.getElementById('toast-root');
  const el = document.createElement('div');
  el.className='toast';
  el.innerHTML = '<span>'+esc(msg)+'</span>'+(undo?'<a data-action="undo-remove">Undo</a>':'')+'<span class="tx" data-action="toast-close">✕</span>';
  root.appendChild(el);
  setTimeout(()=>{ if(el.parentNode) el.parentNode.removeChild(el); }, 8000);
}

/* ---------------- search suggestions ---------------- */
const SUGGS = ['besta','besta storage combination','besta tv unit','besta shelf unit','besta frame','besta cabinet','besta doors','besta legs'];
function renderSuggest(q){
  const box = $('#suggest'); if(!box) return;
  const ql = q.trim().toLowerCase();
  if(ql.length<2){ box.classList.add('hidden'); ui.suggestOpen=false; return; }
  const s = SUGGS.filter(x=>x.indexOf(ql)>=0);
  const prods = CAT.catalog.filter(it=>(it.name+' '+it.description).toLowerCase().indexOf(ql)>=0).slice(0,3);
  box.innerHTML =
    (s.length?'<div class="sg-head">Search suggestions</div>'+s.map(x=>'<div class="sg-item" data-action="sugg-pick" data-q="'+esc(x)+'">'+I.search+'<span>'+esc(x)+'</span></div>').join(''):'<div class="sg-item" data-action="sugg-pick" data-q="'+esc(q)+'">'+I.search+'<span>Search for "<b>'+esc(q)+'</b>"</span></div>')
    + (prods.length?'<div class="sg-head">Products</div>'+prods.map(p=>'<div class="sg-prod" data-nav="'+p.route+'"><img src="'+p.image+'" alt=""><span><b>'+esc(p.name)+'</b><br><span class="muted" style="font-size:12px">'+esc(p.description.slice(0,44))+'</span><br><span class="p">'+money(p.member_price)+'</span></span></div>').join(''):'');
  box.classList.remove('hidden'); ui.suggestOpen=true;
}
function submitSearch(){
  const i = $('#header-search'); if(!i) return;
  const q = i.value.trim(); if(!q) return;
  go('/us/en/search/?q='+encodeURIComponent(q));
}

/* ---------------- global event delegation ---------------- */
document.addEventListener('click', e=>{
  const nav = e.target.closest('[data-nav]');
  if(nav){ e.preventDefault(); ui.megaOpen=false; closeOverlays(); go(nav.getAttribute('data-nav')); return; }
  const a = e.target.closest('[data-action]');
  if(!a){
    if(ui.suggestOpen && !e.target.closest('.searchbox')){ const sg=$('#suggest'); if(sg) sg.classList.add('hidden'); ui.suggestOpen=false; }
    if(ui.megaOpen && !e.target.closest('#mega')){ ui.megaOpen=false; renderHead(); }
    return;
  }
  const act = a.getAttribute('data-action');
  const id = a.getAttribute('data-id');
  switch(act){
    case 'products-toggle': ui.megaOpen=!ui.megaOpen; renderHead(); break;
    case 'mega-tab': ui.megaTab=a.getAttribute('data-tab'); renderHead(); break;
    case 'cookie-ok': S.cookie=true; save(); const c=$('#cookie'); if(c) c.remove(); break;
    case 'cookie-pref': break;
    case 'search-submit': submitSearch(); break;
    case 'search-clear': { const i=$('#header-search'); if(i){ i.value=''; i.focus(); const sc=a; sc.classList.add('hidden'); const sg=$('#suggest'); if(sg) sg.classList.add('hidden'); } break; }
    case 'sugg-pick': go('/us/en/search/?q='+encodeURIComponent(a.getAttribute('data-q'))); break;
    case 'facet': { const f=a.getAttribute('data-f'); if(ui.facets.has(f)) ui.facets.delete(f); else ui.facets.add(f); renderCurrentPage(); break; }
    case 'color-pick': {
      const cur = CUR.params;
      if(cur.get('color')==='white') go(searchURL(cur.get('q'), null, cur.get('sort')));
      else go(searchURL(cur.get('q'), 'white', cur.get('sort')));
      break; }
    case 'chip-clear': go(searchURL(CUR.params.get('q'), null, CUR.params.get('sort'))); break;
    case 'cmp-close': S.compare=[]; save(); renderCurrentPage(); break;
    case 'cmp-go': go('/us/en/compare/'); break;
    case 'compare-remove': S.compare = S.compare.filter(x=>String(x)!==String(id)); save(); renderCurrentPage(); break;
    case 'add': { const it=findItem(id); if(it){ addToBag(it,1); openAddDrawer(it,1); } break; }
    case 'reco-add': { const r=PSEUDO[id]; if(r){ addToBag(r,1); showToast(r.name+' was added to your shopping bag.'); } break; }
    case 'fav': { const ix=S.favs.indexOf(id); if(ix>=0) S.favs.splice(ix,1); else S.favs.push(id); save(); a.classList.toggle('on'); break; }
    case 'pdp-thumb': ui.pdpImg[id]=+a.getAttribute('data-i'); renderCurrentPage(); break;
    case 'open-media': { const it=findItem(id); if(it) openGallery(it,'all'); break; }
    case 'view-3d': showToast('The 3D viewer is not part of this demo.'); break;
    case 'media-tab': ui.galTab=a.getAttribute('data-t'); renderGallery(); break;
    case 'qty-inc': case 'qty-dec': {
      const cur = ui.pdpQty[id]||1;
      let n = act==='qty-inc' ? Math.min(99,cur+1) : Math.max(1,cur-1);
      ui.pdpQty[id]=n;
      const qv=$('#pdp-qv'); if(qv) qv.textContent=n;
      const btn=$('#pdp-add-btn'); if(btn) btn.textContent = n>1 ? 'Add '+n+' items to cart' : 'Add to bag';
      const dec=a.parentElement.querySelector('[data-action="qty-dec"]'); if(dec) dec.classList.toggle('dis', n<=1);
      break; }
    case 'pdp-add': { const it=findItem(id); if(it){ const q=ui.pdpQty[id]||1; addToBag(it,q); ui.pdpQty[id]=1; openAddDrawer(it,q); } break; }
    case 'open-zip': closeOverlays(); openZip(); break;
    case 'zip-save': saveZip(); break;
    case 'open-store': closeOverlays(); openStore(); break;
    case 'store-pick': S.store=a.getAttribute('data-name'); save(); closeOverlays(); renderHead(); renderCurrentPage(); break;
    case 'find-store': break;
    case 'show-parts': openParts(id); break;
    case 'open-reviews': { const it=findItem(id); if(it) openReviews(it); break; }
    case 'rev-sort-btn': ui.rev.sortOpen=!ui.rev.sortOpen; renderReviews(findItem(ui.rev.id)); break;
    case 'rev-topic': ui.rev.topic=a.getAttribute('data-t'); renderReviews(findItem(ui.rev.id)); break;
    case 'rev-summary': ui.rev.hidden=!ui.rev.hidden; renderReviews(findItem(ui.rev.id)); break;
    case 'rev-filter': showToast('Review filters are limited in this recorded slice.'); break;
    case 'write-review': showToast('Writing reviews is not part of this demo.'); break;
    case 'tab-scroll': {
      $$('.pdp-tab').forEach(t=>t.classList.remove('on')); a.classList.add('on');
      const el=document.getElementById(a.getAttribute('data-t')); if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
      break; }
    case 'acc-toggle': a.closest('.acc').classList.toggle('open'); break;
    case 'bag-inc': case 'bag-dec': {
      const it=S.bag.find(i=>String(i.id)===String(id)); if(!it) break;
      it.qty = act==='bag-inc' ? Math.min(99,it.qty+1) : Math.max(1,it.qty-1);
      save(); updateBadge(); renderCurrentPage(); break; }
    case 'bag-remove': {
      const ix=S.bag.findIndex(i=>String(i.id)===String(id)); if(ix<0) break;
      const rm=S.bag[ix]; ui.lastRemoved={item:rm, index:ix};
      S.bag.splice(ix,1); save(); updateBadge(); renderCurrentPage();
      showToast(rm.name+' was removed from your shopping bag.', true);
      break; }
    case 'undo-remove': {
      if(ui.lastRemoved){ const lr=ui.lastRemoved; S.bag.splice(Math.min(lr.index,S.bag.length),0,lr.item); ui.lastRemoved=null; save(); updateBadge(); renderCurrentPage(); }
      const t=e.target.closest('.toast'); if(t) t.remove();
      break; }
    case 'toast-close': { const t=a.closest('.toast'); if(t) t.remove(); break; }
    case 'disc-toggle': ui.discOpen=!ui.discOpen; ui.discErr=false; renderCurrentPage(); break;
    case 'disc-apply': ui.discOpen=true; ui.discErr=true; renderCurrentPage(); setTimeout(()=>{ const i=$('#disc-input'); if(i) i.focus(); },30); break;
    case 'close-overlays': closeOverlays(); break;
  }
});
document.addEventListener('change', e=>{
  const t = e.target;
  if(t.name==='sort' && CUR.path.indexOf('/us/en/search')===0){
    go(searchURL(CUR.params.get('q'), CUR.params.get('color'), t.value)); return;
  }
  if(t.classList.contains('cmp-cb')){
    const id=t.getAttribute('data-id');
    if(t.checked){
      if(S.compare.length>=5){ t.checked=false; showToast('You can compare up to 5 products.'); return; }
      if(S.compare.indexOf(id)<0) S.compare.push(id);
    } else S.compare=S.compare.filter(x=>String(x)!==String(id));
    save(); renderCurrentPage(); return;
  }
  if(t.classList.contains('asm-cb')){
    const it=S.bag.find(i=>String(i.id)===t.getAttribute('data-id'));
    if(it){ it.asm=t.checked; save(); renderCurrentPage(); }
    return;
  }
  if(t.name==='rev-sort' && ui.rev){
    ui.rev.sort=t.value; ui.rev.sortOpen=false; renderReviews(findItem(ui.rev.id)); return;
  }
});
document.addEventListener('input', e=>{
  const t=e.target;
  if(t.id==='header-search'){
    const clr=document.querySelector('.s-clear'); if(clr) clr.classList.toggle('hidden', !t.value);
    renderSuggest(t.value); return;
  }
  if(t.id==='zip-input'){
    const hint=$('#zip-hint'); const v=t.value.trim();
    if(/^\d{5}$/.test(v)){ t.classList.remove('err'); t.classList.add('ok'); hint.className='zip-hint ok'; hint.innerHTML=I.check+' e.g. 19428'; }
    else { t.classList.remove('ok'); if(hint.className.indexOf('err')<0){ hint.className='zip-hint'; hint.textContent='e.g. 19428'; } }
    return;
  }
  if(t.id==='store-search'){ const l=$('#store-list'); if(l) l.innerHTML=storeListHTML(t.value); return; }
  if(t.id==='disc-input'){ t.classList.remove('err'); const er=document.querySelector('.disc-err'); if(er) er.remove(); ui.discErr=false; return; }
});
document.addEventListener('keydown', e=>{
  if(e.key==='Escape'){ closeOverlays(); const sg=$('#suggest'); if(sg){sg.classList.add('hidden'); ui.suggestOpen=false;} if(ui.megaOpen){ui.megaOpen=false; renderHead();} return; }
